from sys import stdin

def main():
	N = int(stdin.readline().strip())
	vectors = [0] * N
	d = 0
	for i in range(N):
		recipe = list(map(int, stdin.readline().strip().split()))
		if recipe[0] == 0:
			vectors[i] = 1 << d
			d += 1
		else:
			for j in recipe[1:]:
				vectors[i] ^= vectors[j - 1]
	Q = int(stdin.readline().strip())
	answer = ''
	for _ in range(Q):
		query = list(map(int, stdin.readline().strip().split()))
		K = query[0]
		s = query[1:]
		vecs = [vectors[i - 1] for i in s]
		linear_dependence = False
		for i in range(K):
			for j in range(i):
				if vecs[i] ^ vecs[j] < vecs[i]:
					vecs[i] ^= vecs[j]
			if vecs[i] == 0:
				linear_dependence = True
				break
		answer += '1' if linear_dependence else '0'
	print(answer)
main()
